/* ---------------------------------------------------------
   STOCKAGE — dans Claude, window.storage est fourni par
   l'environnement. Dans l'APK, il n'existe pas : on le
   remplace ici par un stockage local standard (localStorage),
   avec la même interface asynchrone pour ne rien changer
   au reste du code.
--------------------------------------------------------- */
if (typeof window !== "undefined" && !window.storage) {
  window.storage = {
    async get(key) {
      const raw = window.localStorage.getItem(key);
      if (raw === null) throw new Error("not found");
      return { key, value: raw };
    },
    async set(key, value) {
      window.localStorage.setItem(key, value);
      return { key, value };
    },
    async delete(key) {
      window.localStorage.removeItem(key);
      return { key, deleted: true };
    },
  };
}
