const uid = () => {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
};

function clampInt(value, min, fallback) {
  const n = Math.trunc(Number(value));
  if (!Number.isFinite(n) || n < min) return fallback;
  return n;
}

/* Empêche qu'un double-clic / double-tap déclenche deux fois la même action
   mutante (ex. "Ajouter le tour") avant que l'état ne se mette à jour. */
function useGuardedAction(action) {
  const busyRef = useRef(false);
  const [busy, setBusy] = useState(false);
  const run = useCallback((...args) => {
    if (busyRef.current) return;
    busyRef.current = true;
    setBusy(true);
    try {
      action(...args);
    } finally {
      busyRef.current = false;
      setBusy(false);
    }
  }, [action]);
  return [run, busy];
}

function sanitizeData(parsed) {
  const safe = { ...DEFAULT_DATA };
  if (parsed && typeof parsed === "object") {
    safe.roster = Array.isArray(parsed.roster) ? parsed.roster : DEFAULT_DATA.roster;
    safe.tournaments = Array.isArray(parsed.tournaments) ? parsed.tournaments : DEFAULT_DATA.tournaments;
    safe.matches = Array.isArray(parsed.matches) ? parsed.matches : DEFAULT_DATA.matches;
    safe.scoresheets = Array.isArray(parsed.scoresheets) ? parsed.scoresheets : DEFAULT_DATA.scoresheets;
    safe.theme = parsed.theme === "light" ? "light" : "dark";
  }
  return safe;
}

