/* ---------------------------------------------------------
   CALCULS DE CLASSEMENT
   Inspiré du système FFSC : points de match (PM) cumulés en
   critère principal, différentiel de score en départage.
--------------------------------------------------------- */

/*
 Cas de référence pour rankMatch (à revérifier manuellement après toute
 modification de cette fonction, aucun test automatisé n'existe) :
 - Duel sans égalité   [10, 5]        → pm : [1, 0]
 - Duel à égalité      [10, 10]       → pm : [0.5, 0.5]        (total 1, comme sans égalité)
 - Triangulaire, égalité en tête [10, 10, 5] → pm : [0.75, 0.75, 0]  (total 1.5, comme sans égalité)
 - Quadrette sans égalité [40, 30, 20, 10] → pm : [1, 0.667, 0.333, 0]
*/
function rankMatch(players) {
  const sorted = [...players].sort((a, b) => b.score - a.score);
  const n = sorted.length;
  const out = [];
  let i = 0;
  while (i < n) {
    let j = i;
    while (j + 1 < n && sorted[j + 1].score === sorted[i].score) j++;
    // positions i..j (0-indexées) sont à égalité de score
    const competitionRank = i + 1; // rang affiché, style 1-1-3-4
    let positionSum = 0;
    for (let k = i; k <= j; k++) positionSum += k + 1;
    const avgRank = positionSum / (j - i + 1); // rang moyen, pour que le PM total du match reste constant
    const pm = n > 1 ? (n - avgRank) / (n - 1) : 1;
    for (let k = i; k <= j; k++) {
      const p = sorted[k];
      const others = players.filter((x) => x !== p);
      const avgOthers = others.reduce((s, o) => s + o.score, 0) / (others.length || 1);
      const diff = p.score - avgOthers;
      out.push({ ...p, rank: competitionRank, pm, diff });
    }
    i = j + 1;
  }
  return out.sort((a, b) => a.rank - b.rank);
}

function tournamentStandings(tournament, matches) {
  const rows = {};
  tournament.participants.forEach((name) => {
    rows[name] = { name, matchesPlayed: 0, pm: 0, diff: 0, totalScore: 0 };
  });
  matches
    .filter((m) => m.tournamentId === tournament.id)
    .forEach((m) => {
      const ranked = rankMatch(m.players);
      ranked.forEach((r) => {
        if (!rows[r.name]) rows[r.name] = { name: r.name, matchesPlayed: 0, pm: 0, diff: 0, totalScore: 0 };
        rows[r.name].matchesPlayed += 1;
        rows[r.name].pm += r.pm;
        rows[r.name].diff += r.diff;
        rows[r.name].totalScore += r.score;
      });
    });
  return Object.values(rows).sort(
    (a, b) => b.pm - a.pm || b.diff - a.diff || b.totalScore - a.totalScore
  );
}

async function exportTournamentExcel(tournament, standings, matches) {
  try {
    const wsStandings = XLSX.utils.json_to_sheet(
      standings.map((s, i) => ({
        Rang: i + 1,
        Joueur: s.name,
        PM: Number(s.pm.toFixed(2)),
        "Différentiel": Number(s.diff.toFixed(0)),
        Parties: s.matchesPlayed,
      }))
    );
    const matchRows = [];
    [...matches]
      .sort((a, b) => (a.round || 0) - (b.round || 0) || a.createdAt - b.createdAt)
      .forEach((m) => {
        rankMatch(m.players).forEach((r) => {
          matchRows.push({
            Tour: m.round,
            Joueur: r.name,
            Score: r.score,
            Rang: r.rank,
            "Détail par tour": m.turns && m.turns[r.name] && m.turns[r.name].length ? m.turns[r.name].join(" + ") : "",
          });
        });
      });
    const wsMatches = XLSX.utils.json_to_sheet(matchRows);

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, wsStandings, "Classement");
    XLSX.utils.book_append_sheet(wb, wsMatches, "Matchs");
    const safeName = tournament.name.replace(/[^a-z0-9]+/gi, "_").slice(0, 40) || "tournoi";
    const base64 = XLSX.write(wb, { bookType: "xlsx", type: "base64" });
    await exportFile(
      base64,
      `${safeName}-resultats.xlsx`,
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    );
  } catch (e) {
    console.error("Échec de l'export Excel", e);
    window.alert("Impossible de générer le fichier Excel sur cet appareil.");
  }
}

function buildPlayerStats(matches) {
  const stats = {};
  [...matches]
    .sort((a, b) => a.createdAt - b.createdAt)
    .forEach((m) => {
      const ranked = rankMatch(m.players);
      ranked.forEach((r) => {
        if (!stats[r.name]) stats[r.name] = { name: r.name, scores: [], wins: 0, matches: 0, total: 0 };
        stats[r.name].scores.push(r.score);
        stats[r.name].matches += 1;
        stats[r.name].total += r.score;
        if (r.rank === 1) stats[r.name].wins += 1;
      });
    });
  Object.values(stats).forEach((s) => { s.avg = s.matches ? s.total / s.matches : 0; });
  return stats;
}

