function RankBadge({ rank }) {
  const T = useTheme();
  const colors = { 1: T.goldLight, 2: T.rank2, 3: T.rank3 };
  return (
    <div
      className="w-8 h-8 rounded-md flex items-center justify-center font-bold text-sm shrink-0"
      style={{
        background: colors[rank] || T.rowBg,
        color: colors[rank] ? "#1f2a1c" : T.subtle,
        border: colors[rank] ? "none" : `1px solid ${T.cardBorder}`,
      }}
    >
      {rank}
    </div>
  );
}

function Button({ children, onClick, variant = "solid", type = "button", disabled, className = "" }) {
  const T = useTheme();
  const styles = {
    solid: { background: T.gold, color: "#1f2a1c" },
    green: { background: T.green, color: T.greenText },
    ghost: { background: "transparent", color: T.ghostText, border: `1px solid ${T.ghostBorder}` },
    danger: { background: T.dangerBg, color: T.dangerText },
  };
  return (
    <button
      type={type}
      disabled={disabled}
      onClick={onClick}
      className={`px-4 py-2 rounded-lg font-semibold text-sm flex items-center gap-1.5 justify-center transition disabled:opacity-40 ${className}`}
      style={styles[variant]}
    >
      {children}
    </button>
  );
}

function TextField({ value, onChange, placeholder, onEnter }) {
  const T = useTheme();
  return (
    <input
      value={value}
      onChange={(e) => onChange(e.target.value)}
      onKeyDown={(e) => { if (e.key === "Enter" && onEnter) onEnter(); }}
      placeholder={placeholder}
      className="w-full rounded-lg px-3.5 py-2 text-sm outline-none"
      style={{ background: T.inputBg, color: T.inputText, border: `2px solid ${T.inputBorder}` }}
    />
  );
}

function NumberField({ value, onChange, min = 0, className = "w-24" }) {
  const T = useTheme();
  return (
    <input
      type="number"
      value={value}
      min={min}
      onChange={(e) => onChange(e.target.value)}
      className={`${className} rounded-lg px-3 py-2 text-sm text-center outline-none`}
      style={{ background: T.inputBg, color: T.inputText, border: `2px solid ${T.inputBorder}` }}
    />
  );
}

